// Load uploaded movies from LocalStorage
let uploadedMovies = JSON.parse(localStorage.getItem('uploadedMovies')) || [];
let deletedIds = JSON.parse(localStorage.getItem('deletedIds')) || [];

function slugify(s) {
    return String(s || '')
        .toLowerCase()
        .replace(/[^a-z0-9]+/g, '-')
        .replace(/^-+|-+$/g, '') || 'movie';
}

// Merge sample movies and uploaded movies, filter out permanently deleted
let movies = [...uploadedMovies, ...sampleMovies].filter(m => !deletedIds.includes(m.id));
movies.forEach(m => {
    m.slug = slugify(m.title);
});

function findMovieByParam(value) {
    if (!value) return null;
    const num = Number(value);
    if (!Number.isNaN(num)) {
        const byId = movies.find(m => m.id === num);
        if (byId) return byId;
    }
    const lower = String(value).toLowerCase();
    return movies.find(m => (m.slug || slugify(m.title)).toLowerCase() === lower);
}

// INIT
document.addEventListener('DOMContentLoaded', () => {
    setupScrollAnimations();
    const params = new URLSearchParams(location.search);
    const movieParam = params.get('movie');
    const catParam = params.get('category');
    if (catParam) {
        const filtered = movies.filter(m => (m.category || '').toLowerCase() === catParam.toLowerCase());
        displayMovies(filtered);
        const titleEl = document.querySelector('#movies .section-title');
        if (titleEl) titleEl.textContent = `${catParam.charAt(0).toUpperCase() + catParam.slice(1)} Movies`;
        document.title = `MMS Leak — ${catParam.charAt(0).toUpperCase() + catParam.slice(1)} Movies`;
        const can = document.querySelector('link[rel="canonical"]');
        if (can) can.setAttribute('href', `${location.origin}${location.pathname}?category=${encodeURIComponent(catParam)}`);
    } else {
        displayMovies(movies);
        document.title = 'MMS Leak - Watch MMS LEAK VIDEOS Online';
        const can = document.querySelector('link[rel="canonical"]');
        if (can) can.setAttribute('href', `${location.origin}${location.pathname}`);
    }
    if (movieParam) {
        const movie = findMovieByParam(movieParam);
        if (movie) {
            openMovieModal(movie);
            document.title = `${movie.title} - Watch Online | MMS Leak`;
            const can = document.querySelector('link[rel="canonical"]');
            const slug = movie.slug || movie.id;
            if (can) can.setAttribute('href', `${location.origin}${location.pathname}?movie=${encodeURIComponent(slug)}`);
        }
    }
    updateVisitorStats();
    setupEventListeners();
    const addMovieParam = params.get('addMovie');
    if(addMovieParam) {
        try {
            const jsonStr = decodeURIComponent(escape(atob(addMovieParam)));
            const incoming = JSON.parse(jsonStr);
            let uploadedMovies = JSON.parse(localStorage.getItem('uploadedMovies')) || [];
            const exists = uploadedMovies.some(m => m.id === incoming.id);
            if(!exists) {
                uploadedMovies.unshift(incoming);
                localStorage.setItem('uploadedMovies', JSON.stringify(uploadedMovies));
            }
            movies = [...uploadedMovies, ...sampleMovies].filter(m => !deletedIds.includes(m.id));
            displayMovies(movies);
            alert('Movie added from shared link');
        } catch(e) {}
    }
});

// DISPLAY MOVIES
function displayMovies(list) {
    moviesGrid.innerHTML = '';

    list.forEach(movie => {
        const card = createMovieCard(movie);
        moviesGrid.appendChild(card);
        observer.observe(card);
    });
}

// CREATE CARD
function createMovieCard(movie) {
    const card = document.createElement('div');
    card.className = 'movie-card fade-in';
    card.dataset.id = movie.id;
    card.dataset.slug = movie.slug || '';

    // Admin Controls (Only visible for Admin)
    const adminControls = isAdmin ? `
        <div class="admin-controls" style="position: absolute; top: 10px; right: 10px; z-index: 10; display: flex; gap: 5px;">
            <button class="edit-btn" onclick="editMovie(${movie.id}, event)" style="background: #ffc107; border: none; color: #000; padding: 5px 10px; border-radius: 5px; cursor: pointer;"><i class="fas fa-edit"></i></button>
            <button class="delete-btn" onclick="deleteMovie(${movie.id}, event)" style="background: #dc3545; border: none; color: #fff; padding: 5px 10px; border-radius: 5px; cursor: pointer;"><i class="fas fa-trash"></i></button>
        </div>
    ` : '';

    const views = "0";

    card.innerHTML = `
        <div class="movie-poster" style="position: relative;">
            <img src="${movie.poster}" alt="${movie.title}">
            ${adminControls}
            <div class="views-badge"><i class="fas fa-eye"></i> ${views}</div>
        </div>
        <div class="movie-info">
            <h3>${movie.title}</h3>
            <p>${movie.description}</p>
            <div class="movie-meta">
                <span class="movie-category">${movie.category}</span>
                <span class="movie-duration">${movie.duration}</span>
            </div>
            <a href="${movie.video}" class="download-btn" target="_blank" onclick="event.stopPropagation()" style="display: block; text-align: center; background: #333; color: white; padding: 8px; margin-top: 10px; border-radius: 5px; text-decoration: none;">
                <i class="fas fa-download"></i> Download / Watch
            </a>
        </div>
    `;

    card.addEventListener('click', (e) => {
        if (!e.target.closest('button') && !e.target.closest('a')) {
            const slug = movie.slug || movie.id;
            const url = `${location.origin}${location.pathname}?movie=${encodeURIComponent(slug)}`;
            history.pushState({ movieId: movie.id }, '', url);
            openMovieModal(movie);
        }
    });
    const watchBtn = card.querySelector('.download-btn');
    if (watchBtn) {
        watchBtn.addEventListener('click', (e) => {
            e.preventDefault();
            e.stopPropagation();
            const slug = movie.slug || movie.id;
            const url = `${location.origin}${location.pathname}?movie=${encodeURIComponent(slug)}`;
            history.pushState({ movieId: movie.id }, '', url);
            openMovieModal(movie);
        });
    }
    const badge = card.querySelector('.views-badge');
    fetch(`https://api.countapi.xyz/get/${COUNTAPI_NS}/movie_${movie.id}_views`).then(r=>r.json()).then(d=>{
        if(badge && d && d.value!=null) badge.innerHTML = `<i class="fas fa-eye"></i> ${d.value}`;
    }).catch(()=>{});
    return card;
}

// HELPER: Get Embed URL
function getEmbedUrl(url) {
    if (!url) return "";
    
    if (url.includes("youtube.com") || url.includes("youtu.be")) {
        let videoId = "";
        if (url.includes("youtu.be")) {
            videoId = url.split("/").pop();
        } else if (url.includes("v=")) {
            videoId = url.split("v=")[1].split("&")[0];
        }
        return `https://www.youtube.com/embed/${videoId}?autoplay=1`;
    }
    
    if (url.includes("drive.google.com")) {
        return url.replace("/view", "/preview");
    }
    
    return url;
}

function getDriveId(url) {
    if(!url || !url.includes('drive.google.com')) return null;
    const m = url.match(/\/file\/d\/([^/]+)\//);
    return m ? m[1] : null;
}

function showPlaybackError(originalUrl) {
    const el = document.getElementById('playbackError');
    if(!el) return;
    const id = getDriveId(originalUrl);
    const preview = getEmbedUrl(originalUrl);
    const download = id ? `https://drive.google.com/uc?export=download&id=${id}` : originalUrl;
    const btnOriginal = document.getElementById('btnOpenOriginal');
    const btnPreview = document.getElementById('btnOpenPreview');
    const btnDownload = document.getElementById('btnOpenDownload');
    if(btnOriginal) btnOriginal.href = originalUrl;
    if(btnPreview) btnPreview.href = preview;
    if(btnDownload) btnDownload.href = download;
    el.style.display = 'block';
}

function openMovieModal(movie) {
    document.getElementById('modalMovieTitle').textContent = movie.title;
    document.getElementById('modalMovieDescription').textContent = movie.description;
    document.getElementById('modalMovieCategory').textContent = movie.category;
    document.getElementById('modalMovieDuration').textContent = movie.duration;

    const hasEpisodes = Array.isArray(movie.episodes) && movie.episodes.length > 0;
    if (hasEpisodes) {
        renderEpisodeList(movie, 0);
        playEpisode(movie, 0);
    } else {
        const embedUrl = getEmbedUrl(movie.video);
        if (movie.video.match(/\.(mp4|webm|ogg)$/i)) {
            videoContainer.innerHTML = `
                <video id="moviePlayer" controls autoplay style="position: absolute; top: 0; left: 0; width: 100%; height: 100%; border-radius: 20px 20px 0 0;">
                    <source src="${movie.video}" type="video/mp4">
                    Your browser does not support the video tag.
                </video>
            `;
            const v = document.getElementById('moviePlayer');
            const errEl = document.getElementById('playbackError');
            if(errEl) errEl.style.display = 'none';
            if(v) v.addEventListener('error', () => showPlaybackError(movie.video));
        } else {
            videoContainer.innerHTML = `
                <iframe 
                    src="${embedUrl}" 
                    style="position: absolute; top: 0; left: 0; width: 100%; height: 100%; border-radius: 20px 20px 0 0;"
                    frameborder="0" 
                    allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture" 
                    allowfullscreen>
                </iframe>
            `;
            const errEl = document.getElementById('playbackError');
            if(errEl) errEl.style.display = 'none';
            const ifr = videoContainer.querySelector('iframe');
            let loaded = false;
            if(ifr) {
                ifr.addEventListener('load', () => { loaded = true; });
                setTimeout(() => { if(!loaded) showPlaybackError(movie.video); }, 4000);
            }
        }
        movieModal.style.display = 'block';
        fetch(`https://api.countapi.xyz/hit/${COUNTAPI_NS}/total_views`).then(r=>r.json()).then(d=>{
            const viewsEl = document.getElementById('statTotalViews');
            if(viewsEl && d && d.value!=null) viewsEl.textContent = d.value;
        }).catch(()=>{});
        fetch(`https://api.countapi.xyz/hit/${COUNTAPI_NS}/movie_${movie.id}_views`).then(r=>r.json()).then(d=>{
            const card = document.querySelector(`.movie-card[data-id="${movie.id}"]`);
            const badge = card ? card.querySelector('.views-badge') : null;
            if(badge && d && d.value!=null) badge.innerHTML = `<i class="fas fa-eye"></i> ${d.value}`;
            if(isAdmin) renderViewsChart();
        }).catch(()=>{});
    }
}

function closeMovieModal() {
    movieModal.style.display = 'none';
    videoContainer.innerHTML = ''; // Stop video/audio
}

function bufferToHex(buffer) {
    const bytes = new Uint8Array(buffer);
    let hex = '';
    for (let i = 0; i < bytes.length; i++) {
        hex += bytes[i].toString(16).padStart(2, '0');
    }
    return hex;
}

function hashPassword(password) {
    if (!password) return Promise.resolve('');
    if (!window.crypto || !window.crypto.subtle) {
        return Promise.resolve(password);
    }
    const enc = new TextEncoder();
    return crypto.subtle.digest('SHA-256', enc.encode(password)).then(bufferToHex);
}

// ADMIN FUNCTIONS
async function toggleAdminMode() {
    if (isAdmin) {
        isAdmin = false;
        uploadSection.style.display = 'none';
        adminDashboard.style.display = 'none';
        if (adminBtn) adminBtn.innerHTML = '<i class="fas fa-user-shield"></i> Admin';
        alert("Admin Mode Disabled");
    } else {
        const stored = localStorage.getItem(ADMIN_HASH_KEY);
        if (!stored) {
            const newPass = prompt("Set a new Admin Password (only this browser will remember it):");
            if (!newPass) {
                alert("Password not set.");
                return;
            }
            const confirmPass = prompt("Confirm Admin Password:");
            if (newPass !== confirmPass) {
                alert("Passwords do not match.");
                return;
            }
            try {
                const hash = await hashPassword(newPass);
                localStorage.setItem(ADMIN_HASH_KEY, hash);
                isAdmin = true;
                uploadSection.style.display = 'block';
                adminDashboard.style.display = 'block';
                if (adminBtn) adminBtn.innerHTML = '<i class="fas fa-unlock"></i> Logout';
                alert("Admin password saved on this browser. Admin Mode Enabled.");
            } catch (e) {
                alert("Error setting password.");
                return;
            }
        } else {
            const password = prompt("Enter Admin Password:");
            if (!password) {
                alert("Wrong Password!");
                return;
            }
            try {
                const hash = await hashPassword(password);
                if (hash === stored) {
                    isAdmin = true;
                    uploadSection.style.display = 'block';
                    adminDashboard.style.display = 'block';
                    if (adminBtn) adminBtn.innerHTML = '<i class="fas fa-unlock"></i> Logout';
                    alert("Welcome Admin! You can now upload and delete movies.");
                } else {
                    alert("Wrong Password!");
                    return;
                }
            } catch (e) {
                alert("Wrong Password!");
                return;
            }
        }
    }
    displayMovies(movies); // Re-render to show/hide delete buttons
}

function deleteMovie(id, event) {
    event.stopPropagation(); // Prevent modal from opening
    if (confirm("Are you sure you want to delete this movie?")) {
        movies = movies.filter(m => m.id !== id);
        
        // Remove from LocalStorage
        let uploadedMovies = JSON.parse(localStorage.getItem('uploadedMovies')) || [];
        uploadedMovies = uploadedMovies.filter(m => m.id !== id);
        localStorage.setItem('uploadedMovies', JSON.stringify(uploadedMovies));

        // Persist deletion across refresh for any movie id
        let deletedIds = JSON.parse(localStorage.getItem('deletedIds')) || [];
        if (!deletedIds.includes(id)) {
            deletedIds.push(id);
            localStorage.setItem('deletedIds', JSON.stringify(deletedIds));
        }

        displayMovies(movies);
        alert("Movie deleted successfully!");
    }
}

function editMovie(id, event) {
    event.stopPropagation();
    const movie = movies.find(m => m.id === id);
    if (!movie) return;

    // Clear and create one entry
    const container = document.getElementById('movieEntries');
    container.innerHTML = '';
    addMovieEntry();

    // Populate form
    const entry = container.querySelector('.movie-entry');
    entry.querySelector('.movie-title').value = movie.title;
    entry.querySelector('.movie-category').value = movie.category;
    entry.querySelector('.movie-description').value = movie.description;
    entry.querySelector('.movie-video').value = movie.video;
    // Handle episodes if needed
    if (movie.episodes && movie.episodes.length) {
        entry.querySelector('.movie-episodes').value = movie.episodes.map(e => e.video).join('\n');
    }
    
    // Set edit mode
    isEditing = true;
    editingId = id;
    
    // Change button text
    const btn = movieUploadForm.querySelector('button[type="submit"]');
    btn.innerHTML = '<i class="fas fa-sync"></i> Update Movie';
    
    // Show upload section if hidden
    uploadSection.style.display = 'block';
    
    // Scroll to form
    uploadSection.scrollIntoView({ behavior: 'smooth' });
}


// UPLOAD / UPDATE MOVIE
async function handleMovieUpload() {
    const entries = document.querySelectorAll('.movie-entry');
    if (!entries.length) return;

    const escapeVal = (s) => {
        if (s == null) return "";
        return String(s).replace(/\\/g, "\\\\").replace(/"/g, '\\"').replace(/\n/g, "\\n");
    };
    
    const buildCode = (m) => {
        const fields = [
            `id: ${m.id}`,
            `title: "${escapeVal(m.title)}"`,
            `description: "${escapeVal(m.description)}"`,
            `duration: "${escapeVal(m.duration)}"`,
            `views: "${escapeVal(m.views)}"`,
            `poster: "${m.poster}"`,
            `category: "${escapeVal(m.category)}"`,
            `video: "${escapeVal(m.video)}"`
        ];
        let ep = "";
        if (Array.isArray(m.episodes) && m.episodes.length > 0) {
            const eps = m.episodes.map(e => `        { title: "${escapeVal(e.title)}", video: "${escapeVal(e.video)}" }`).join(',\n');
            ep = `,\n    episodes: [\n${eps}\n    ]`;
        }
        return `{\n    ${fields.join(',\n    ')}${ep}\n}`;
    };

    const processEntry = (entry) => {
        return new Promise((resolve, reject) => {
            const title = entry.querySelector('.movie-title').value;
            const category = entry.querySelector('.movie-category').value;
            const description = entry.querySelector('.movie-description').value;
            const video = entry.querySelector('.movie-video').value;
            const episodesRaw = entry.querySelector('.movie-episodes').value;
            const posterFile = entry.querySelector('.movie-poster').files[0];

            const finish = (posterData) => {
                const newId = isEditing ? editingId : Date.now() + Math.floor(Math.random() * 1000);
                const movieData = {
                    id: newId,
                    title, description, category, 
                    duration: "Unknown", 
                    views: "0",
                    poster: posterData, 
                    video
                };
                const lines = (episodesRaw || '').split('\n').map(s=>s.trim()).filter(Boolean);
                if(lines.length > 0) {
                    movieData.episodes = lines.map((u, i) => ({ title: `Episode ${i+1}`, video: u }));
                }
                resolve(movieData);
            };

            if (isEditing && !posterFile) {
                // Keep existing poster
                const existing = movies.find(m => m.id === editingId);
                finish(existing.poster);
            } else {
                if (!posterFile) {
                    reject(new Error(`Please select a poster image for "${title || 'Untitled'}"`));
                    return;
                }
                const reader = new FileReader();
                reader.onloadend = () => finish(reader.result);
                reader.readAsDataURL(posterFile);
            }
        });
    };

    try {
        const promises = Array.from(entries).map(processEntry);
        const moviesList = await Promise.all(promises);

        let uploadedMovies = JSON.parse(localStorage.getItem('uploadedMovies')) || [];

        if (isEditing) {
            const movieData = moviesList[0];
            // Remove old version
            uploadedMovies = uploadedMovies.filter(m => m.id !== editingId);
            // Add updated version
            uploadedMovies.unshift(movieData);
            
            // Update in local memory
            const idx = movies.findIndex(m => m.id === editingId);
            if (idx !== -1) movies[idx] = movieData;
            
            alert("Movie updated successfully!");
        } else {
            // Bulk add
            // Reverse to keep order (first form entry at top)
            // But usually we prepend. If I add [A, B], I want A then B? 
            // If I prepend A then B, B is top.
            // Let's prepend them in reverse order so first entry ends up at top.
            for (let i = moviesList.length - 1; i >= 0; i--) {
                uploadedMovies.unshift(moviesList[i]);
                movies.unshift(moviesList[i]);
            }
            alert(`${moviesList.length} Movie(s) uploaded successfully!`);
        }

        localStorage.setItem('uploadedMovies', JSON.stringify(uploadedMovies));
        displayMovies(movies);

        // Reset Form
        document.getElementById('movieUploadForm').reset();
        // Reset entries to just one
        const container = document.getElementById('movieEntries');
        container.innerHTML = '';
        addMovieEntry(); // Function to add one fresh entry
        
        isEditing = false;
        editingId = null;
        const btn = movieUploadForm.querySelector('button[type="submit"]');
        btn.innerHTML = '<i class="fas fa-upload"></i> Upload All Movies';

        // Generate Code
        const sec = document.getElementById('generatedCodeSection');
        const out = document.getElementById('generatedCode');
        if (sec && out) {
            const codes = moviesList.map(m => buildCode(m)).join(',\n');
            out.value = codes;
            sec.style.display = 'block';
        }
        
    } catch (error) {
        alert(error.message);
    }
}

// Add Entry Helper
function addMovieEntry() {
    const container = document.getElementById('movieEntries');
    const template = `
        <div class="movie-entry" style="background: rgba(255,255,255,0.05); padding: 20px; border-radius: 10px; margin-bottom: 20px; position: relative;">
            <div class="form-group">
                <label>Movie Title</label>
                <input type="text" class="movie-title" required>
            </div>
            <div class="form-group">
                <label>Category</label>
                <select class="movie-category" required>
                    <option value="">Select Category</option>
                    <option value="mms video">MMS VIDEO</option>
                    <option value="viral video">VIRAL VIDEO</option>
                    <option value="tiktoker Video">TIKTOKER VIDEO</option>
                    <option value="action">Action</option>
                    <option value="wild">WILD</option>
                    <option value="Indian">INDIAN</option>
                </select>
            </div>
            <div class="form-group">
                <label>Description</label>
                <textarea class="movie-description" rows="4" required></textarea>
            </div>
            <div class="form-group">
                <label>Poster Image (Upload File)</label>
                <input type="file" class="movie-poster" accept="image/*">
            </div>
            <div class="form-group">
                <label>Video URL (Google Drive/Direct Link)</label>
                <input type="url" class="movie-video" placeholder="https://drive.google.com/..." required>
            </div>
            <div class="form-group" style="display:flex;align-items:center;gap:10px;">
                <input type="checkbox" class="publish-public" />
                <label>Publish globally (generate code to add)</label>
            </div>
            <div class="form-group">
                <label>Episodes (optional, one URL per line)</label>
                <textarea class="movie-episodes" rows="4" placeholder="https://...&#10;https://..."></textarea>
            </div>
            <button type="button" class="remove-entry-btn" style="background: #dc3545; color: white; border: none; padding: 5px 10px; border-radius: 5px; cursor: pointer; position: absolute; top: 10px; right: 10px;">
                <i class="fas fa-trash"></i>
            </button>
        </div>
    `;
    container.insertAdjacentHTML('beforeend', template);
    
    // Attach event to remove button
    const newEntry = container.lastElementChild;
    newEntry.querySelector('.remove-entry-btn').addEventListener('click', function() {
        if (container.children.length > 1) {
            newEntry.remove();
        } else {
            alert("You must have at least one movie entry.");
        }
    });
}

function setupBulkUploadEvents() {
    const addBtn = document.getElementById('addMovieEntryBtn');
    if (addBtn) {
        addBtn.addEventListener('click', addMovieEntry);
    }
    // Attach remove to initial entry if exists (or we can just re-render it)
    const initialEntry = document.querySelector('.movie-entry');
    if (initialEntry) {
        const removeBtn = initialEntry.querySelector('.remove-entry-btn');
        if (removeBtn) {
            removeBtn.addEventListener('click', function() {
                 if (document.querySelectorAll('.movie-entry').length > 1) {
                    initialEntry.remove();
                } else {
                    alert("You must have at least one movie entry.");
                }
            });
        }
    }
}
document.addEventListener('DOMContentLoaded', setupBulkUploadEvents);


function updateVisitorStats() {
    const visitEl = document.getElementById('statTotalVisits');
    if(visitEl) {
        fetch(`https://api.countapi.xyz/hit/${COUNTAPI_NS}/total_visits`).then(r=>r.json()).then(d=>{
            if(d && d.value!=null) visitEl.textContent = d.value;
        }).catch(()=>{});
    }
    const liveEl = document.getElementById('statLiveUsers');
    if(liveEl) {
        fetch(`https://api.countapi.xyz/hit/${COUNTAPI_NS}/online_users`).then(r=>r.json()).then(d=>{
            if(d && d.value!=null) liveEl.textContent = d.value;
        }).catch(()=>{});
        const poll = () => {
            fetch(`https://api.countapi.xyz/get/${COUNTAPI_NS}/online_users`).then(r=>r.json()).then(d=>{
                if(d && d.value!=null) liveEl.textContent = d.value;
            }).catch(()=>{});
        };
        setInterval(poll, 5000);
        window.addEventListener('beforeunload', async () => {
            try {
                const cur = await fetch(`https://api.countapi.xyz/get/${COUNTAPI_NS}/online_users`).then(r=>r.json());
                if(cur && cur.value!=null) {
                    const v = Math.max(0, cur.value-1);
                    await fetch(`https://api.countapi.xyz/set/${COUNTAPI_NS}/online_users?value=${v}`);
                }
            } catch(e){}
        });
        document.addEventListener('visibilitychange', async () => {
            try {
                if(document.visibilityState === 'hidden') {
                    const cur = await fetch(`https://api.countapi.xyz/get/${COUNTAPI_NS}/online_users`).then(r=>r.json());
                    if(cur && cur.value!=null) {
                        const v = Math.max(0, cur.value-1);
                        await fetch(`https://api.countapi.xyz/set/${COUNTAPI_NS}/online_users?value=${v}`);
                    }
                } else {
                    const d = await fetch(`https://api.countapi.xyz/hit/${COUNTAPI_NS}/online_users`).then(r=>r.json());
                    if(d && d.value!=null) liveEl.textContent = d.value;
                }
            } catch(e){}
        });
    }
    const viewsEl = document.getElementById('statTotalViews');
    if(viewsEl) {
        fetch(`https://api.countapi.xyz/get/${COUNTAPI_NS}/total_views`).then(r=>r.json()).then(d=>{
            if(d && d.value!=null) viewsEl.textContent = d.value;
        }).catch(()=>{});
        setInterval(() => {
            fetch(`https://api.countapi.xyz/get/${COUNTAPI_NS}/total_views`).then(r=>r.json()).then(d=>{
                if(d && d.value!=null) viewsEl.textContent = d.value;
            }).catch(()=>{});
        }, 5000);
    }
    const moviesEl = document.getElementById('statTotalMovies');
    if(moviesEl) moviesEl.textContent = movies.length;
}

function renderViewsChart() {
    const el = document.getElementById('viewsChart');
    if(!el || !window.Chart) return;
    const fetches = movies.map(m => fetch(`https://api.countapi.xyz/get/${COUNTAPI_NS}/movie_${m.id}_views`).then(r=>r.json()).then(d=>({movie:m, count:(d&&d.value!=null)?d.value:0})).catch(()=>({movie:m, count:0})));
    Promise.all(fetches).then(items => {
        items.sort((a,b)=>b.count-a.count);
        const top = items.slice(0,5);
        const labels = top.map(x=>x.movie.title);
        const data = top.map(x=>x.count);
        if(viewsChartInstance) { viewsChartInstance.destroy(); }
        viewsChartInstance = new Chart(el.getContext('2d'), {
            type: 'bar',
            data: { labels, datasets: [{ label: 'Views', data, backgroundColor: '#e50914' }] },
            options: { responsive: true, plugins: { legend: { display: false } }, scales: { y: { beginAtZero: true } } }
        });
    });
}

function renderEpisodeList(movie, activeIndex) {
    const el = document.getElementById('episodeList');
    if(!el) return;
    el.style.display = 'block';
    el.dataset.active = String(activeIndex);
    const items = movie.episodes.map((ep, i) => {
        const a = i === activeIndex ? '#e50914' : '#fff';
        const b = i === activeIndex ? '#333' : '#222';
        return `<button data-index="${i}" style="display:block;width:100%;text-align:left;margin:5px 0;padding:10px;border:1px solid #333;border-radius:8px;background:${b};color:${a};cursor:pointer">Episode ${i+1}</button>`;
    }).join('');
    el.innerHTML = items;
    el.querySelectorAll('button[data-index]').forEach(btn=>{
        btn.addEventListener('click', (e)=>{
            const idx = parseInt(btn.getAttribute('data-index'));
            renderEpisodeList(movie, idx);
            playEpisode(movie, idx);
        });
    });
}

function playEpisode(movie, index) {
    const ep = movie.episodes[index];
    const url = getEmbedUrl(ep.video);
    if (ep.video.match(/\.(mp4|webm|ogg)$/i)) {
        videoContainer.innerHTML = `
            <video id="moviePlayer" controls autoplay style="position: absolute; top: 0; left: 0; width: 100%; height: 100%; border-radius: 20px 20px 0 0;">
                <source src="${ep.video}" type="video/mp4">
                Your browser does not support the video tag.
            </video>
        `;
        const v = document.getElementById('moviePlayer');
        const errEl = document.getElementById('playbackError');
        if(errEl) errEl.style.display = 'none';
        if(v) v.addEventListener('error', () => showPlaybackError(ep.video));
    } else {
        videoContainer.innerHTML = `
            <iframe 
                src="${url}" 
                style="position: absolute; top: 0; left: 0; width: 100%; height: 100%; border-radius: 20px 20px 0 0;"
                frameborder="0" 
                allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture" 
                allowfullscreen>
            </iframe>
        `;
        const errEl = document.getElementById('playbackError');
        if(errEl) errEl.style.display = 'none';
        const ifr = videoContainer.querySelector('iframe');
        let loaded = false;
        if(ifr) {
            ifr.addEventListener('load', () => { loaded = true; });
            setTimeout(() => { if(!loaded) showPlaybackError(ep.video); }, 4000);
        }
    }
    movieModal.style.display = 'block';
    fetch(`https://api.countapi.xyz/hit/${COUNTAPI_NS}/total_views`).then(r=>r.json()).then(d=>{
        const viewsEl = document.getElementById('statTotalViews');
        if(viewsEl && d && d.value!=null) viewsEl.textContent = d.value;
    }).catch(()=>{});
    fetch(`https://api.countapi.xyz/hit/${COUNTAPI_NS}/movie_${movie.id}_views`).then(r=>r.json()).then(d=>{
        const card = document.querySelector(`.movie-card[data-id="${movie.id}"]`);
        const badge = card ? card.querySelector('.views-badge') : null;
        if(badge && d && d.value!=null) badge.innerHTML = `<i class="fas fa-eye"></i> ${d.value}`;
    }).catch(()=>{});
    fetch(`https://api.countapi.xyz/hit/${COUNTAPI_NS}/movie_${movie.id}_ep_${index}_views`).catch(()=>{});
    if(isAdmin) renderViewsChart();
}

// EVENTS
function setupEventListeners() {
    if(adminBtn) adminBtn.addEventListener('click', (e) => {
        e.preventDefault(); // Prevent scrolling to top
        toggleAdminMode();
    });
    // Category card clicks -> open category page (same index with query)
    if (categoryCards && categoryCards.length) {
        categoryCards.forEach(card => {
            card.addEventListener('click', () => {
                const cat = card.dataset.category;
                if (!cat) return;
                const url = `${location.origin}${location.pathname}?category=${encodeURIComponent(cat)}`;
                location.href = url;
            });
        });
    }
    // Footer category links (#hollywood etc.) -> redirect to query param page
    document.querySelectorAll('a[href^="#"]').forEach(a => {
        const hash = (a.getAttribute('href') || '').replace('#','').toLowerCase();
        if (['hollywood','bollywood','netflix','action','comedy','drama'].includes(hash)) {
            a.addEventListener('click', (e) => {
                e.preventDefault();
                const url = `${location.origin}${location.pathname}?category=${encodeURIComponent(hash)}`;
                location.href = url;
            });
        }
    });
    window.addEventListener('keydown', (e) => {
        if(e.key && e.key.toLowerCase() === 'g') {
            e.preventDefault();
            toggleAdminMode();
        }
    });

    // Form Submit
    movieUploadForm.addEventListener('submit', e => {
        e.preventDefault();
        handleMovieUpload();
    });

    // Modal Close (X button)
    document.querySelector('.close').addEventListener('click', closeMovieModal);
    
    // Modal Close (Click Outside)
    window.addEventListener('click', (e) => {
        if (e.target === movieModal) {
            closeMovieModal();
        }
    });
    
    // Subscribe Button
    const subBtn = document.querySelector('.subscribe-btn');
    if(subBtn) {
        subBtn.addEventListener('click', () => {
            alert("Thank you for subscribing! You will get updates.");
            subBtn.innerHTML = '<i class="fas fa-check"></i> Subscribed';
            subBtn.style.background = '#28a745';
        });
    }
}

// SCROLL ANIMATION
function setupScrollAnimations() {
    observer = new IntersectionObserver(entries => {
        entries.forEach(entry => {
            if (entry.isIntersecting) {
                entry.target.classList.add('visible');
            }
        });
    }, { threshold: 0.1 });
}
